import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, Select, Tiles } from '../kit';
import type { PageProps, Row } from '../kit';

// 오류 유형에 대응하는 메시지가 없을 때 쓰는 일반 오류 안내
const GENERAL_MESSAGE = '처리 중 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.';

// 오류 유형별 사용자 안내 메시지 (내부 시스템 정보·개인정보는 담지 않는다)
// EXTERNAL_FAILED는 가정: 외부 시스템 연계 실패 사유를 사용자에게 알리는 안내 유형
const CATALOG: Row[] = [
  { code: 'VALIDATION_FAILED', label: '입력 오류', message: '입력한 내용을 확인해 주세요. 필수 값이 비었거나 형식이 맞지 않습니다.' },
  { code: 'UNAUTHORIZED', label: '인증 필요', message: '로그인이 필요합니다. 다시 로그인해 주세요.' },
  { code: 'FORBIDDEN', label: '권한 없음', message: '이 기능을 사용할 권한이 없습니다.' },
  { code: 'EXTERNAL_FAILED', label: '외부 시스템 연계 오류', message: '외부 시스템 연계에 실패했습니다. 실패 사유를 확인한 뒤 다시 시도해 주세요.' },
  { code: 'INTERNAL_ERROR', label: '서버 오류', message: '서버에서 오류가 발생했습니다. 잠시 후 다시 시도해 주세요.' },
];

function messageOf(code: string): string {
  const found = CATALOG.find((row) => row.code === code);
  return found ? String(found.message) : GENERAL_MESSAGE;
}

export default function FnSir00302Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [code, setCode] = useState('');

  const options: [string, string][] = [
    ...CATALOG.map((row): [string, string] => [String(row.code), String(row.label)]),
    ['UNDEFINED', '정의되지 않은 오류'],
  ];

  async function onSubmit() {
    if (!code) {
      throw new Error('오류 유형을 선택해 주세요.');
    }
    // 선택한 유형의 안내 메시지를 Form이 화면에 보인다
    throw new Error(messageOf(code));
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>안내 현황</h2>
        <Tiles
          items={[
            ['정의된 오류 유형', CATALOG.length],
            ['일반 오류 안내', 1],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>오류 메시지</h2>
        <Band total={CATALOG.length}>
          <button type="button" onClick={() => { setCode(''); setOpen(true); }}>
            오류 메시지 확인
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'code', label: '오류 유형', render: (row) => <Badge value={row.code} /> },
            { key: 'label', label: '구분' },
            { key: 'message', label: '안내 메시지' },
          ]}
          rows={CATALOG}
          empty="정의된 오류 메시지가 없습니다."
        />
      </section>
      <section className="box span-4">
        <h2>일반 오류 안내</h2>
        <p>{GENERAL_MESSAGE}</p>
        <p>유형에 맞는 메시지가 정의되어 있지 않으면 위 안내를 표시합니다.</p>
      </section>
      {open && (
        <Drawer title="오류 메시지 확인" onClose={() => setOpen(false)}>
          <Form onSubmit={onSubmit} submit="오류 발생시키기" note="선택한 오류 유형의 안내 메시지가 폼 아래에 표시됩니다.">
            <Field label="오류 유형" required wide>
              <Select value={code} onChange={setCode} options={options} placeholder="선택" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
